void bus_status_notify_brake_off (void *arg)
{
  if (timeout_test (d2d_delay_timeout))
    {
	   d2d_tx(SET_BRAKE_OFF);
	}
  else
    {
	   bus_status_tx_delay = TRUE; //set up flag for delayed TX 
	}	
	
}

//--------------------------------------------------------------------------//

void bus_status_notify_brake_on (void *arg)
{
	if (timeout_test (d2d_delay_timeout))
	  {
		 d2d_tx(SET_BRAKE_ON);	
	  }
	else
      {
	     bus_status_tx_delay = FALSE; // clear flag for delayed TX since the status has not changed
	  }
}

//--------------------------------------------------------------------------//

void bus_status_notify_brake_d2d_delay (void *arg)
{
   if (bus_status_tx_delay == TRUE)
   {
	  d2d_tx(SET_BRAKE_OFF);
	  bus_status_tx_delay = FALSE;
   }

}

